<main class="product-page"><section><img id="main-image" class="main-image" src="<?=e($images[0]['image_url']??'')?>" alt="<?=e($p['name'])?>"><div class="thumbs"><?php foreach($images as $i=>$img):?><img class="<?=!$i?'active':''?>" data-main-image src="<?=e($img['image_url'])?>" alt="<?=e($img['alt_text'])?>"><?php endforeach;?></div></section><section class="product-info"><div class="eyebrow"><?=e($p['category_name'])?> / REGULAR ORDER</div><h1><?=e($p['name'])?></h1><div class="price"><?=money((float)$p['price'])?></div><p class="stock mt-3"><i data-lucide="circle-check"></i> <?= $p['stock'] ?> pieces available</p><div class="divider"></div><p class="leading-7 text-slate-600"><?=nl2br(e($p['description']))?></p><form method="post" action="<?=url('cart.php') ?>"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><div class="divider"></div><div class="flex justify-between"><strong class="text-sm">Pilih ukuran</strong><button class="text-link border-0 bg-transparent cursor-pointer" type="button" data-modal="#size-chart">SIZE CHART (CM)</button></div><div class="size-options mt-3"><?php foreach($sizes as $i=>$s):?><label class="size-option <?=$s['code']==='P_LENGTH'||$s['code']==='L_WIDTH'?'long':''?>"><input required type="radio" name="size_code" value="<?=e($s['code'])?>" data-name="<?=e($s['display_name'])?>" <?=$i===0?'checked':''?>><span><?=e($s['display_name'])?></span></label><?php endforeach;?></div><?php if($variants):?><div class="mt-6"><strong class="text-sm">Pilihan varian</strong><select class="field w-full mt-2" name="variant"><?php foreach($variants as $v):?><option value="<?=e($v['variant_name'])?>"><?=e($v['variant_name'])?></option><?php endforeach;?></select></div><?php endif;?><?php if($motifs):?><div class="mt-5"><strong class="text-sm">Pilihan motif</strong><select class="field w-full mt-2" name="motif"><?php foreach($motifs as $m):?><option value="<?=e($m['name'])?>"><?=e($m['name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="divider"></div><div class="flex gap-4 items-center"><div class="quantity"><button type="button" onclick="this.nextElementSibling.stepDown()">−</button><input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1"><button type="button" onclick="this.previousElementSibling.stepUp()">+</button></div><button class="btn flex-1" type="submit">ADD TO CART <i data-lucide="shopping-bag"></i></button></div></form><form method="post" action="<?=url('cart.php')?>" class="mt-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="buy"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="size_code" value="<?=$sizes[0]['code']??'M'?>"><button class="btn gold w-full" type="submit">BUY NOW</button></form><p class="text-xs text-slate-500 mt-5">Material: <?=e($p['material'])?></p></section></main><div id="size-chart" class="modal"><div class="modal-box"><button class="close-modal">×</button><div class="eyebrow">PRODUCT MEASUREMENT</div><h2 class="text-3xl">Size chart</h2><p class="text-sm text-slate-500">Panjang dan lebar ditampilkan dalam sentimeter. Ukuran bisa berbeda pada setiap model.</p><table><thead><tr><th>Ukuran</th><th>Panjang</th><th>Lebar</th><th>Catatan</th></tr></thead><tbody><?php foreach($chart as $r):?><tr><td><?=e($r['label'])?></td><td><?=e((string)$r['length_cm'])?> cm</td><td><?=e((string)$r['width_cm'])?> cm</td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php'; ?>
